/* ATELIER V1 — greffe locale pour Atlas deleuzien V9 */
(function(){
'use strict';

const DB_NAME='atlas-deleuzien-atelier-v1';
const DB_VERSION=1;
const PROJECT_STORE='projects';
const FILE_STORE='files';
const STATUS=['given','hypothesis','candidate','active','locked','demoted','rejected','open'];
const STATUS_LABEL={given:'DONNÉ',hypothesis:'HYPOTHÈSE',candidate:'CANDIDAT',active:'ACTIF',locked:'LOCK',demoted:'RÉTROGRADÉ',rejected:'REJETÉ',open:'OUVERT'};
const DECISION_LABEL={keep:'CONSERVER',demote:'RÉTROGRADER',reject:'REJETER',leave_open:'LAISSER OUVERT'};
const TEST_KEYS=[['necessity','Nécessité'],['substitutability','Substituabilité'],['excess','Excédent'],['materiality','Matérialité'],['consequence','Conséquence']];
const LEVELS=['','low','medium','high','very_high'];
const LEVEL_LABEL={'':'—',low:'Faible',medium:'Moyenne',high:'Forte',very_high:'Très forte'};
const RELATION_TYPES=[
 ['causalite','CAUSALITÉ','Un élément produit directement une conséquence.'],
 ['condition','CONDITION','Un élément rend une autre opération possible sans la produire à lui seul.'],
 ['contrainte','CONTRAINTE','Une règle ou limite réduit le champ des possibles et oriente ce qui peut arriver.'],
 ['transformation','TRANSFORMATION','La ligne décrit un changement de fonction, d’état, de relation ou de régime.'],
 ['succession','SUCCESSION','Les éléments se suivent sans que leur ordre affirme une causalité.'],
 ['accumulation','ACCUMULATION','Des occurrences s’ajoutent jusqu’à modifier progressivement la configuration.'],
 ['repetition_variation','RÉPÉTITION / VARIATION','Une forme revient et ses écarts deviennent opératoires.'],
 ['parallelisme','PARALLÉLISME','Deux lignes évoluent ensemble sans se produire directement l’une l’autre.'],
 ['contamination','CONTAMINATION','Une ligne modifie progressivement le fonctionnement d’une autre.'],
 ['requalification','REQUALIFICATION','Un élément ultérieur change la fonction ou la lecture d’un élément antérieur.'],
 ['association_montage','ASSOCIATION / MONTAGE','Le sens ou l’effet naît du rapprochement de formes plutôt que d’un lien causal.'],
 ['rituel_programme','RITUEL / PROGRAMME','L’ordre est produit par une règle, une procédure ou un protocole.'],
 ['champ_distribue','CHAMP / PRESSION DISTRIBUÉE','Plusieurs relations agissent ensemble sans cause centrale unique.']
];
const RELATION_LABEL=Object.fromEntries(RELATION_TYPES.map(([k,l])=>[k,l]));
function relationOptions(current=''){return `<option value="">— nature de la relation —</option>`+RELATION_TYPES.map(([k,l,d])=>`<option value="${k}" ${k===current?'selected':''}>${l}</option>`).join('')}
function relationHelp(k=''){const x=RELATION_TYPES.find(r=>r[0]===k);return x?x[2]:''}
let dbPromise=null;

function id(prefix='x'){return prefix+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8)}
function now(){return new Date().toISOString()}
function fmtDate(v){try{return new Intl.DateTimeFormat('fr-BE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch(_){return v||''}}
function norm(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function pill(status){return `<span class="atelier-pill ${esc(status)}">${esc(STATUS_LABEL[status]||status)}</span>`}
function statusOptions(current,allowed=STATUS){return allowed.map(s=>`<option value="${s}" ${s===current?'selected':''}>${STATUS_LABEL[s]||s}</option>`).join('')}
function levelOptions(current=''){return LEVELS.map(s=>`<option value="${s}" ${s===current?'selected':''}>${LEVEL_LABEL[s]}</option>`).join('')}
function clone(x){return JSON.parse(JSON.stringify(x))}

function openDB(){
 if(dbPromise)return dbPromise;
 dbPromise=new Promise((resolve,reject)=>{
  if(!('indexedDB' in window)){reject(new Error('IndexedDB indisponible'));return}
  const req=indexedDB.open(DB_NAME,DB_VERSION);
  req.onupgradeneeded=()=>{
   const db=req.result;
   if(!db.objectStoreNames.contains(PROJECT_STORE))db.createObjectStore(PROJECT_STORE,{keyPath:'id'});
   if(!db.objectStoreNames.contains(FILE_STORE))db.createObjectStore(FILE_STORE,{keyPath:'id'});
  };
  req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error);
 });
 return dbPromise;
}
function storeReq(store,mode,fn){return openDB().then(db=>new Promise((resolve,reject)=>{const tx=db.transaction(store,mode);const os=tx.objectStore(store);let req;try{req=fn(os)}catch(e){reject(e);return}req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}))}
const getProject=pid=>storeReq(PROJECT_STORE,'readonly',os=>os.get(pid));
const getProjects=()=>storeReq(PROJECT_STORE,'readonly',os=>os.getAll());
const putProject=p=>storeReq(PROJECT_STORE,'readwrite',os=>os.put(p));
const deleteProjectRecord=pid=>storeReq(PROJECT_STORE,'readwrite',os=>os.delete(pid));
const putFile=f=>storeReq(FILE_STORE,'readwrite',os=>os.put(f));
const getFile=fid=>storeReq(FILE_STORE,'readonly',os=>os.get(fid));
const deleteFile=fid=>storeReq(FILE_STORE,'readwrite',os=>os.delete(fid));

function newSession(title){return {id:id('session'),title:title||'Nouvelle session',status:'active',materials:[],formulations:[],activeProblem:'',exclusions:[],resources:[],constraints:[],lines:[],candidates:[],decisions:[],consequences:[],openQuestions:[],audits:[],finalDecision:null,sourceDecision:null,createdAt:now(),updatedAt:now()}}
function newProject(title){return {id:id('project'),title:title||'Nouveau projet',createdAt:now(),updatedAt:now(),materials:[],sessions:[],projectLocks:[],projectOpenQuestions:[]}}
function findSession(p,sid){return (p.sessions||[]).find(s=>s.id===sid)}
async function mutateProject(pid,fn){const p=await getProject(pid);if(!p)throw new Error('Projet introuvable');await fn(p);p.updatedAt=now();await putProject(p);return p}
function rerender(){const parts=current().split('/');atelierMount(parts[0],decodeURIComponent(parts.slice(1).join('/')||''))}

function atelierHomePage(){return shell(`<div class="page-intro atelier-intro"><div class="atelier-kicker">Appareil de concentration</div><h2>Atelier</h2><p>Projets, sessions, contraintes, candidats, tests et décisions. L’Atelier ne génère pas l’œuvre à ta place : il garde la généalogie des choix et aide à concentrer les possibles.</p></div><div class="atelier-manifesto"><b>L’Atelier ne sert pas à produire davantage d’idées.</b><br>Il sert à concentrer les possibilités jusqu’à ce qu’un geste paraisse nécessaire.</div><div id="atelierRoot" class="atelier-grid"><div class="atelier-empty">Chargement des projets…</div></div>`,{title:'Atelier',sub:'Formuler → ouvrir → contraindre → converger → tester → trancher',klass:'atelier-page'})}
function atelierProjectPage(arg){return shell(`<div id="atelierRoot"><div class="atelier-empty">Chargement du projet…</div></div>`,{title:'Atelier',sub:'Projet',klass:'atelier-page'})}
function atelierSessionPage(arg){return shell(`<div id="atelierRoot"><div class="atelier-empty">Chargement de la session…</div></div>`,{title:'Atelier',sub:'Session',klass:'atelier-page'})}

async function seedIfEmpty(){
 if(localStorage.getItem('atlas-atelier-v1-seeded'))return;
 const all=await getProjects(); if(all.length){localStorage.setItem('atlas-atelier-v1-seeded','1');return;}
 const p=newProject('Deuxième cerveau');
 p.materials=[
  {id:id('mat'),type:'note',title:'Image-cristal 1',content:'Un ordinateur sans écran, enterré dans la terre, constitue le deuxième cerveau d’une personne morte.',status:'given',createdAt:now()},
  {id:id('mat'),type:'note',title:'Image-cristal 2',content:'À la cérémonie d’enterrement, un hologramme IA semble parfois connaître le mort plus intimement que ses proches.',status:'given',createdAt:now()},
  {id:id('mat'),type:'note',title:'Données d’intention',content:'Traces fines de la formation d’un choix : reformulations, rejets, corrections, bifurcations, reprises et sélections. Elles ne sont pas l’intention elle-même.',status:'given',createdAt:now()},
  {id:id('mat'),type:'note',title:'Culture de la trouvaille',content:'Dans un monde où l’accès et la reproduction sont faciles, ce qui oblige à chercher peut acquérir une valeur nouvelle.',status:'hypothesis',createdAt:now()}
 ];
 const s=newSession('Construire le récit depuis deux images');
 s.activeProblem='Dans un monde où presque tout est immédiatement accessible et reproductible, que devient le désir de connaître lorsqu’un mort laisse une dernière résistance à l’accès ?';
 s.formulations=[{id:id('problem'),version:1,text:s.activeProblem,status:'active',createdAt:now()}];
 s.resources=[
  {id:id('resource'),atlas:'atlas2',type:'Atlas 2 · Transformation',page:'atlas2-transformation/transformation-trace',label:'TRACE',reason:'Le deuxième cerveau et l’hologramme ne restituent pas le mort : ils font persister des effets, des données et des possibilités d’interprétation après sa disparition.',status:'active'},
  {id:id('resource'),atlas:'atlas2',type:'Atlas 2 · Configuration',page:'atlas2-configuration/config-lecture',label:'CONFIGURATION DE LECTURE',reason:'Une donnée ne devient signifiante qu’à travers la manière dont le personnage la sélectionne, la rapproche d’autres traces et accepte de la requalifier.',status:'active'},
  {id:id('resource'),atlas:'atlas1',type:'Concept',page:'concept/'+encodeURIComponent('Image-cristal'),label:'Image-cristal',reason:'Le raccord sert à penser la coexistence de plusieurs régimes de présence et de temps sans réduire l’hologramme à une copie transparente du mort.',status:'active'}
 ];
 s.exclusions=['Le problème n’est pas principalement : une IA peut-elle remplacer un humain ?','Le trésor ne doit pas devenir une simple récompense narrative.'];
 s.constraints=[
  {id:id('constraint'),text:'Aucune instance ne possède la version vraie du mort.',status:'locked',reason:'Préserver plusieurs modes de connaissance incompatibles.'},
  {id:id('constraint'),text:'Aucun indice n’a été fabriqué comme indice.',status:'locked',reason:'Les traces deviennent indices par changement de regard.'},
  {id:id('constraint'),text:'Chaque accès doit produire une nouvelle opacité.',status:'locked',reason:'Trouver doit déplacer le mystère plutôt que le résoudre.'},
  {id:id('constraint'),text:'Action causalement nette ; sens jamais totalement épuisé par sa cause.',status:'locked',reason:'Préserver l’aura sans sacrifier la causalité.'}
 ];
 s.lines=[
  {id:id('line'),label:'Matière',elements:'corps → terre → serveur → lumière',relationType:'succession',context:'La ligne suit les supports matériels successifs par lesquels la présence du mort change de régime : du corps enterré au serveur caché, puis à la lumière de l’hologramme. Les termes condensent des supports précis et ne valent pas comme explication autonome.'},
  {id:id('line'),label:'Connaissance',elements:'souvenir → modèle → archive → trace → interprétation',relationType:'requalification',context:'Le projet oppose plusieurs façons de connaître le mort. Le souvenir des proches, le modèle IA, l’archive et les traces ne convergent pas vers une version unique : chacun reconfigure ce qui peut être interprété.'},
  {id:id('line'),label:'Accès',elements:'accessible → caché → trouvé → illisible',relationType:'requalification',context:'Chaque gain d’accès déplace l’opacité au lieu de l’abolir. Ce qui devient matériellement trouvable peut rester difficile à lire, et la trouvaille transforme donc le problème plutôt qu’elle ne le clôt.'},
  {id:id('line'),label:'Personnage',elements:'chercher → interpréter → sélectionner',relationType:'rituel_programme',context:'Le personnage ne progresse pas seulement en découvrant des informations : il doit choisir quelles traces suivre, quelle interprétation retenir provisoirement et ce qu’il accepte d’abandonner.'},
  {id:id('line'),label:'Mort',elements:'absence → continuation → fragmentation',relationType:'transformation',context:'La mort ne produit pas une disparition simple. Des dispositifs prolongent certaines présences, mais cette continuation fragmente l’identité au lieu de restituer une totalité du mort.'}
 ];
 const c1={id:id('candidate'),type:'scene',label:'L’enterrement rassemble le corps, la terre et l’hologramme.',status:'locked',supportsLines:s.lines.map(x=>x.id),tests:{},createdAt:now()};
 const c2={id:id('candidate'),type:'structure',label:'Le deuxième cerveau est trouvé autour du milieu du film.',status:'locked',supportsLines:s.lines.filter(x=>['Accès','Connaissance','Personnage'].includes(x.label)).map(x=>x.id),tests:{necessity:{level:'high',reason:'La trouvaille doit transformer le régime du film.'},substitutability:{level:'low',reason:'La repousser à la fin réduit le film à une localisation.'},excess:{level:'high',reason:'Elle inverse rareté et surabondance.'},materiality:{level:'very_high',reason:'Objet physique, terre, poids, absence d’écran.'},consequence:{level:'very_high',reason:'Toute la seconde moitié doit changer de problème.'}},createdAt:now()};
 const c3={id:id('candidate'),type:'character',label:'Le chasseur n’a jamais connu le mort.',status:'locked',supportsLines:s.lines.filter(x=>['Personnage','Connaissance'].includes(x.label)).map(x=>x.id),tests:{},createdAt:now()};
 const c4={id:id('candidate'),type:'structure',label:'Une fausse trouvaille révèle un prototype antérieur.',status:'rejected',supportsLines:[],tests:{},createdAt:now()};
 const c5={id:id('candidate'),type:'structure',label:'L’archive contient une grande recherche inachevée à poursuivre.',status:'demoted',supportsLines:s.lines.filter(x=>x.label==='Connaissance').map(x=>x.id),tests:{},createdAt:now()};
 s.candidates=[c1,c2,c3,c4,c5];
 s.decisions=[
  {id:id('decision'),candidateId:c1.id,action:'keep',reason:'L’enterrement est une convergence matérielle et conceptuelle forte.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c2.id,action:'keep',reason:'La trouvaille ouvre le deuxième film au lieu de le clore.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c3.id,action:'keep',reason:'L’intimité avec le mort se construit depuis les traces plutôt que depuis le souvenir.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c4.id,action:'reject',reason:'Le rebondissement sent le scénario et n’est pas nécessaire.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c5.id,action:'demote',reason:'Bonne possibilité, mais risque de remplacer le premier MacGuffin par une mission posthume.',status:'locked',createdAt:now()}
 ];
 const d2=s.decisions[1];
 s.consequences=[
  {id:id('consequence'),originDecision:d2.id,text:'La seconde moitié ne peut plus avoir pour moteur principal la localisation du cerveau.',status:'active'},
  {id:id('consequence'),originDecision:d2.id,text:'L’accès au cerveau doit créer un nouveau problème plutôt qu’une résolution.',status:'active'},
  {id:id('consequence'),originDecision:d2.id,text:'L’hologramme et l’archive brute doivent rester structurellement distincts.',status:'active'}
 ];
 s.openQuestions=[{id:id('open'),text:'Pourquoi le mort a-t-il enterré son deuxième cerveau ?',status:'open',keepOpen:true,reason:'Aucune décision actuelle n’exige de fermer cette question.'}];
 s.finalDecision={candidateId:c2.id,status:'locked',why:'Cette forme est préférable parce qu’elle empêche la trouvaille du deuxième cerveau de fonctionner comme récompense finale. En plaçant l’accès au milieu du film, la découverte devient une contrainte nouvelle qui oblige le projet à changer de moteur plutôt qu’à simplement résoudre une recherche.',problemResponse:'Le problème initial portait sur le désir de connaître face à une dernière résistance à l’accès. La décision tranche en séparant l’accès matériel de l’accès intelligible : le cerveau peut être trouvé sans que le mort devienne lisible. La seconde moitié doit donc déplacer la question de « où est-il ? » vers « que peut-on réellement comprendre de ce qui a été trouvé ? ».',abandoned:'Sont abandonnées la structure de chasse au trésor jusqu’au dernier acte et l’idée qu’un objet caché puisse fournir à lui seul la vérité du mort. Leur abandon évite que toute l’architecture converge vers une simple révélation finale.',imposed:'À partir de cette décision, la seconde moitié doit posséder un autre moteur dramatique que la localisation. Le serveur doit produire des données interprétables mais non totalisables ; l’hologramme et l’archive brute doivent rester distincts ; le personnage doit sélectionner, comparer et parfois renoncer. Le montage doit faire sentir que chaque gain d’accès redistribue les questions au lieu de les fermer.',unforeseen:'La trouvaille précoce fait apparaître un conflit plus intéressant entre surabondance et opacité : le problème n’est plus le manque d’informations mais l’impossibilité de décider lesquelles comptent. Elle rend aussi le personnage responsable de ses choix d’interprétation, puisque l’archive ne peut plus jouer le rôle d’autorité finale.',newProblem:'Comment faire de la surabondance de traces une difficulté dramatique active sans transformer la seconde moitié en enquête explicative ou en exposition d’archives ?',createdAt:now(),updatedAt:now(),lockedAt:now(),candidateSnapshot:{label:c2.label,type:c2.type,description:'La découverte matérielle intervient assez tôt pour obliger le récit à changer de problème au lieu de fermer la recherche.'}};
 const s2=newSession('Cycle suivant — après la trouvaille');
 s2.activeProblem=s.finalDecision.newProblem;
 s2.formulations=[{id:id('problem'),version:1,text:s2.activeProblem,status:'active',createdAt:now()}];
 s2.sourceDecision={sessionId:s.id,candidateId:c2.id,label:c2.label,text:s.finalDecision.problemResponse,lockedAt:s.finalDecision.lockedAt};
 s2.constraints=[{id:id('constraint'),text:'Aucune séquence d’archive ne peut fonctionner comme explication totale du mort.',status:'locked',reason:'La décision précédente a séparé accès matériel et intelligibilité ; la suite doit préserver cette conséquence.'}];
 s2.materials=[{id:id('mat'),type:'note',title:'Héritage du cycle précédent',content:'Le cerveau est déjà trouvé. Le nouveau problème porte sur la sélection, la lecture et les effets des traces disponibles.',status:'given',createdAt:now()}];
 p.sessions.push(s,s2); await putProject(p); localStorage.setItem('atlas-atelier-v1-seeded','1');
}


async function seedDionysosIfMissing(){
 const all=await getProjects();
 if(all.some(p=>p.title==='Dionysos Suspendu — cas de validation'))return;
 const p=newProject('Dionysos Suspendu — cas de validation');
 p.materials=[
  {id:id('mat'),type:'note',title:'Problème de création',content:'Comment faire traverser une transformation corporelle et archaïque sans expliquer explicitement ce qu’elle signifie ?',status:'given',createdAt:now()},
  {id:id('mat'),type:'note',title:'Lignes déjà identifiées',content:'Corps, espace, son, caméra et motifs doivent travailler ensemble sans que l’une de ces lignes serve de commentaire explicatif aux autres.',status:'given',createdAt:now()}
 ];
 const s=newSession('Concentrer la transformation dans une forme');
 s.activeProblem='Comment faire traverser une transformation corporelle et archaïque sans expliquer explicitement ce qu’elle signifie ?';
 s.formulations=[{id:id('problem'),version:1,text:s.activeProblem,status:'active',createdAt:now()}];
 s.resources=[
  {id:id('resource'),atlas:'atlas2',type:'Atlas 2 · Transformation',page:'atlas2-transformation/transformation-condensation',label:'CONDENSATION',reason:'Le problème demande qu’une forme matérielle porte plusieurs lignes de transformation à la fois, au lieu de les expliquer séparément par le dialogue ou le commentaire.',status:'active'},
  {id:id('resource'),atlas:'atlas2',type:'Atlas 2 · Configuration',page:'atlas2-configuration/config-contrainte-generatrice',label:'CONTRAINTE GÉNÉRATRICE',reason:'Une forme physique forte peut réduire les possibilités de mise en scène et obliger corps, espace, son et caméra à se réorganiser autour d’elle.',status:'active'},
  {id:id('resource'),atlas:'atlas1',type:'Atlas 1 · Artaud',page:'work-artaud-theatre',label:'LANGAGE PHYSIQUE / POÉSIE DANS L’ESPACE',reason:'Ce raccord est utile seulement comme opération de pensée : chercher une transformation qui passe par l’espace, le corps, le son et le geste plutôt que par une explication discursive du sens.',status:'active'}
 ];
 s.exclusions=[
  'Ne pas résoudre la transformation par un dialogue qui en donnerait la signification.',
  'Ne pas transformer les motifs archaïques en dictionnaire symbolique.',
  'Ne pas traiter la suspension comme une image autonome détachée du reste de la mise en scène.'
 ];
 s.constraints=[
  {id:id('constraint'),text:'La transformation doit être perceptible matériellement avant d’être interprétable.',status:'locked',reason:'Le corps, le son, l’espace et la caméra doivent porter le changement sans commentaire explicatif.'},
  {id:id('constraint'),text:'Chaque motif doit avoir une fonction dans la configuration et non une signification fixe.',status:'locked',reason:'Préserver le garde-fou Atlas : même motif ≠ même fonction.'},
  {id:id('constraint'),text:'La forme retenue doit obliger au moins plusieurs lignes de l’œuvre à se réorganiser.',status:'locked',reason:'Une trouvaille forte doit devenir génératrice et non rester décorative.'}
 ];
 s.lines=[
  {id:id('line'),label:'Corps',elements:'appui → perte d’appui → suspension → autre régime corporel',relationType:'transformation',context:'La ligne décrit un changement de régime du corps. La suspension n’est pas supposée expliquer ce changement : elle doit le rendre perceptible par le poids, les tensions, les appuis devenus impossibles et la nouvelle manière d’occuper l’espace.'},
  {id:id('line'),label:'Espace',elements:'sol / verticalité / vide / hauteur',relationType:'condition',context:'Le vide et la hauteur sont les conditions spatiales qui donnent une fonction à la suspension. Sans eux, le corps suspendu redeviendrait seulement une pose ; avec eux, l’espace détermine ce qui peut ou non être fait.'},
  {id:id('line'),label:'Son',elements:'présence → raréfaction → souffle / vibration',relationType:'repetition_variation',context:'Le son ne raconte pas la transformation. Une matière sonore peut revenir en se raréfiant ou en changeant de fonction, jusqu’à ce que souffle et vibration déplacent la perception du corps sans fournir de traduction verbale.'},
  {id:id('line'),label:'Caméra',elements:'observer → approcher → contourner → perdre l’axe stable',relationType:'repetition_variation',context:'La caméra peut reprendre le même corps sous des positions progressivement moins stabilisantes. Le mouvement visuel ne cause pas la transformation ; il varie la manière dont elle devient accessible au spectateur.'},
  {id:id('line'),label:'Motifs',elements:'matière / archaïque / geste / suspension',relationType:'association_montage',context:'Les motifs sont rapprochés par la composition, le geste et le montage. Ils ne constituent pas une chaîne de causes ni un code symbolique : leur association épaissit la même transformation sans lui attribuer une définition unique.'}
 ];
 const c1={id:id('candidate'),type:'geste / dispositif',label:'Le corps suspendu',description:'Un corps réellement soustrait à son appui ordinaire devient le point où corps, espace, son, caméra et motifs doivent converger. La suspension vaut comme contrainte matérielle et non comme symbole à décoder.',status:'locked',supportsLines:s.lines.map(x=>x.id),tests:{necessity:{level:'very_high',reason:'La forme concentre les cinq lignes déjà identifiées et oblige leur mise en scène à partager une même condition matérielle.'},substitutability:{level:'low',reason:'Une simple posture ou un dialogue explicatif ne produiraient pas la même redistribution du poids, de l’espace, du son et du point de vue.'},excess:{level:'high',reason:'La suspension peut produire durée, vulnérabilité, étrangeté et nouvelles relations spatiales au-delà de la seule idée de transformation.'},materiality:{level:'very_high',reason:'La forme existe concrètement dans le corps, les appuis, la hauteur, la durée, le cadre et le son.'},consequence:{level:'very_high',reason:'Une fois retenue, elle oblige la caméra, le son, le rythme et l’organisation de l’espace à être repensés autour de cette contrainte.'}},createdAt:now()};
 const c2={id:id('candidate'),type:'montage',label:'Accumuler des motifs archaïques',description:'Multiplier des signes, matières et objets pourrait densifier l’atmosphère, mais sans garantie qu’ils transforment réellement la configuration ou le corps.',status:'demoted',supportsLines:s.lines.filter(x=>['Motifs','Son'].includes(x.label)).map(x=>x.id),tests:{necessity:{level:'low',reason:'L’accumulation peut être réduite sans changer le problème central.'},substitutability:{level:'high',reason:'Beaucoup d’autres motifs pourraient jouer la même fonction décorative.'},excess:{level:'medium',reason:'Le montage pourrait produire des associations imprévues.'},materiality:{level:'high',reason:'Les motifs sont présents dans l’image et le son.'},consequence:{level:'low',reason:'Ils n’obligent pas à eux seuls le reste de l’œuvre à changer.'}},createdAt:now()};
 const c3={id:id('candidate'),type:'énonciation',label:'Faire expliquer la transformation par une voix',description:'La voix pourrait clarifier le sens de ce qui arrive au corps, mais elle résoudrait discursivement le problème que l’œuvre cherche précisément à faire traverser sans l’expliquer.',status:'rejected',supportsLines:s.lines.filter(x=>x.label==='Son').map(x=>x.id),tests:{necessity:{level:'low',reason:'L’explication verbale n’est pas nécessaire à la perception de la transformation.'},substitutability:{level:'very_high',reason:'N’importe quelle formulation explicative pourrait remplir cette fonction.'},excess:{level:'low',reason:'Elle ferme plutôt qu’elle n’ouvre les conséquences sensibles.'},materiality:{level:'medium',reason:'La voix est matérielle mais son rôle resterait principalement explicatif.'},consequence:{level:'low',reason:'Elle évite de faire travailler ensemble corps, espace et caméra.'}},createdAt:now()};
 s.candidates=[c1,c2,c3];
 s.decisions=[
  {id:id('decision'),candidateId:c1.id,action:'keep',reason:'Le corps suspendu possède la densité formelle la plus forte : une même forme oblige plusieurs lignes différentes sans devoir les commenter.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c2.id,action:'demote',reason:'L’accumulation de motifs peut rester une ressource locale mais elle ne doit pas devenir le moteur principal.',status:'locked',createdAt:now()},
  {id:id('decision'),candidateId:c3.id,action:'reject',reason:'La voix explicative contourne le problème au lieu de le résoudre formellement.',status:'locked',createdAt:now()}
 ];
 s.finalDecision={candidateId:c1.id,status:'locked',why:'Le corps suspendu est retenu parce qu’il ne se contente pas d’illustrer une transformation : il impose une condition matérielle commune au corps, à l’espace, au son, à la caméra et aux motifs. Cette convergence lui donne une densité formelle supérieure aux solutions qui ajouteraient seulement des signes ou une explication.',problemResponse:'Le problème était de faire traverser une transformation corporelle et archaïque sans expliquer ce qu’elle signifie. La suspension tranche en déplaçant la compréhension vers une expérience de poids, de perte d’appui, de vide, de durée et de point de vue. Le spectateur peut donc percevoir qu’un régime corporel change sans recevoir une définition discursive de ce changement.',abandoned:'Sont abandonnées comme solutions principales l’explication par la voix et l’accumulation de symboles archaïques. Elles peuvent éventuellement subsister localement, mais elles ne doivent ni traduire la transformation ni remplacer le travail matériel du corps et de l’espace.',imposed:'La décision oblige désormais l’espace à fournir une hauteur et un vide réels, la caméra à trouver des positions qui rendent la perte d’appui sensible, le son à travailler souffle, vibration et raréfaction plutôt qu’explication, et le rythme à laisser durer suffisamment la situation pour que la suspension cesse d’être une simple image spectaculaire.',unforeseen:'La suspension fait apparaître un nouveau risque : plus elle est visuellement forte, plus elle peut se figer en symbole immédiatement reconnaissable. Elle crée aussi une possibilité intéressante de variation : le même dispositif peut changer de fonction selon la durée, le degré de maîtrise du corps, le rapport au vide et la manière dont la caméra s’y engage.',newProblem:'Comment faire varier le corps suspendu pour qu’il reste une contrainte génératrice et une transformation en cours, plutôt qu’une image fixe dont le spectateur pourrait épuiser immédiatement le sens ?',createdAt:now(),updatedAt:now(),lockedAt:now(),candidateSnapshot:{label:c1.label,type:c1.type,description:c1.description}};
 const s2=newSession('Cycle suivant — faire varier la suspension');
 s2.activeProblem=s.finalDecision.newProblem;
 s2.formulations=[{id:id('problem'),version:1,text:s2.activeProblem,status:'active',createdAt:now()}];
 s2.sourceDecision={sessionId:s.id,candidateId:c1.id,label:c1.label,text:s.finalDecision.problemResponse,relationType:'nouveau_probleme',relationContext:'La forme retenue produit elle-même ce nouveau problème : sa densité visuelle risque de la figer, ce qui oblige le cycle suivant à travailler la variation de sa fonction.',lockedAt:s.finalDecision.lockedAt};
 s2.constraints=[
  {id:id('constraint'),text:'La suspension doit changer de fonction au cours de l’œuvre sans perdre sa matérialité.',status:'locked',reason:'Le nouveau cycle doit éviter la répétition illustrative d’une image déjà comprise.'},
  {id:id('constraint'),text:'Chaque variation doit modifier au moins une relation concrète entre corps, espace, son ou caméra.',status:'locked',reason:'La variation doit produire des conséquences et non seulement une différence plastique.'}
 ];
 s2.materials=[{id:id('mat'),type:'note',title:'Héritage de la décision précédente',content:'Le corps suspendu est LOCK comme forme génératrice. Le problème n’est plus de le choisir mais de découvrir comment ses reprises changent de fonction.',status:'given',createdAt:now()}];
 p.sessions.push(s,s2);
 await putProject(p);
}

async function mountHome(){
 const root=document.getElementById('atelierRoot');if(!root)return;
 try{await seedIfEmpty();await seedDionysosIfMissing();let projects=await getProjects();projects.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));
 root.innerHTML=`<div class="atelier-toolbar"><button class="atelier-btn primary" onclick="atelierNewProject()">＋ Nouveau projet</button><button class="atelier-btn" onclick="document.getElementById('atelierImportProject').click()">Importer un projet</button><input id="atelierImportProject" type="file" accept="application/json,.json" hidden onchange="atelierImportProject(this)"></div>${projects.length?`<div class="atelier-grid atelier-project-grid">${projects.map(projectCard).join('')}</div>`:`<div class="atelier-empty">Aucun projet. Crée le premier.</div>`}<div class="atelier-note"><strong>Stockage V1 :</strong> les projets sont conservés localement dans IndexedDB. Les fichiers attachés restent eux aussi locaux. Le moteur IA n’est pas encore branché : la structure de session, les raccords Atlas manuels et les audits mécaniques sont déjà utilisables.</div>`;
 }catch(e){root.innerHTML=`<div class="atelier-audit bad"><b>Stockage indisponible</b>${esc(e.message)}</div>`}
}
function projectCard(p){const active=(p.sessions||[]).filter(s=>s.status==='active').length;return `<article class="atelier-project-card"><div><div class="atelier-kicker">Projet</div><h3>${esc(p.title)}</h3><p>${p.materials?.length||0} matériau(x) · ${p.sessions?.length||0} session(s) · ${active} active(s)</p><div class="atelier-meta"><span class="atelier-pill active">${esc(fmtDate(p.updatedAt))}</span></div></div><div><button class="atelier-btn" onclick="go('atelier-project/${encodeURIComponent(p.id)}')">Ouvrir ›</button></div></article>`}

async function mountProject(pid){
 const root=document.getElementById('atelierRoot');if(!root)return;const p=await getProject(pid);if(!p){root.innerHTML='<div class="atelier-empty">Projet introuvable.</div>';return}
 const mats=(p.materials||[]).map(m=>materialRow(p,m)).join('');
 const sessions=(p.sessions||[]).slice().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).map(s=>sessionCard(p,s)).join('');
 root.innerHTML=`<div class="atelier-project-head"><div><div class="atelier-kicker">Projet Atelier</div><h2>${esc(p.title)}</h2><p>Dernière modification : ${esc(fmtDate(p.updatedAt))}</p></div><div class="atelier-row-actions"><button class="atelier-btn" onclick="atelierRenameProject('${p.id}')">Renommer</button><button class="atelier-btn" onclick="atelierExportProject('${p.id}')">Exporter JSON</button></div></div>
 <div class="atelier-toolbar"><button class="atelier-btn primary" onclick="atelierNewSession('${p.id}')">＋ Nouvelle session</button><button class="atelier-btn" onclick="atelierAddNote('${p.id}')">＋ Note</button><button class="atelier-btn" onclick="document.getElementById('atelierFileInput').click()">Joindre un fichier</button><input id="atelierFileInput" type="file" accept=".pdf,.docx,.txt,.md,image/*" hidden onchange="atelierAttachFile('${p.id}',this)"></div>
 <section class="atelier-card"><div class="atelier-kicker">Matériaux du projet</div>${mats||'<div class="atelier-empty">Aucun matériau.</div>'}</section>
 <section class="atelier-card"><div class="atelier-kicker">Sessions</div>${sessions||'<div class="atelier-empty">Aucune session.</div>'}</section>
 <div class="atelier-danger-zone"><button class="atelier-btn danger" onclick="atelierDeleteProject('${p.id}')">Supprimer le projet</button></div>`;
}
function materialRow(p,m){const file=m.fileId;return `<div class="atelier-row"><div class="atelier-row-main">${file?`<div class="atelier-file"><span class="atelier-file-icon">${esc((m.extension||'FILE').slice(0,4).toUpperCase())}</span><div><b>${esc(m.title||m.fileName||'Fichier')}</b><small>${esc(m.fileName||'')} ${m.size?`· ${Math.round(m.size/1024)} Ko`:''}</small></div></div>`:`<b>${esc(m.title||'Note')}</b><small>${esc((m.content||'').slice(0,220))}</small>`}</div><div class="atelier-row-actions"><select class="atelier-status-select" onchange="atelierSetMaterialStatus('${p.id}','${m.id}',this.value)">${statusOptions(m.status||'given',['given','hypothesis','candidate','locked','rejected','open'])}</select>${file?`<button class="atelier-btn" onclick="atelierDownloadFile('${m.fileId}')">Ouvrir</button>`:''}<button class="atelier-btn ghost" onclick="atelierDeleteMaterial('${p.id}','${m.id}')">×</button></div></div>`}
function sessionCard(p,s){const dec=(s.decisions||[]).length;return `<div class="atelier-row"><div class="atelier-row-main"><b>${esc(s.title)}</b><small>${esc(s.activeProblem||'Problème non formulé')}<br>${dec} décision(s) · ${esc(fmtDate(s.updatedAt||s.createdAt))}</small><div class="atelier-meta">${pill(s.status==='closed'?'locked':'active')}</div></div><div class="atelier-row-actions"><button class="atelier-btn" onclick="go('atelier-session/${encodeURIComponent(p.id)}/${encodeURIComponent(s.id)}')">Ouvrir ›</button></div></div>`}

async function mountSession(arg){
 const [pid,sid]=String(arg).split('/').map(decodeURIComponent);const root=document.getElementById('atelierRoot');if(!root)return;const p=await getProject(pid);const s=p&&findSession(p,sid);if(!p||!s){root.innerHTML='<div class="atelier-empty">Session introuvable.</div>';return}
 const progress=[!!s.activeProblem,(s.resources||[]).length>0,(s.constraints||[]).length>0,(s.lines||[]).length>0,(s.candidates||[]).length>0,(s.decisions||[]).length>0];
 const audits=computeAudits(s);
 root.innerHTML=`<div class="atelier-project-head"><div><div class="atelier-kicker">${esc(p.title)}</div><h2>${esc(s.title)}</h2><div class="atelier-session-status">${pill(s.status==='closed'?'locked':'active')}<span class="atelier-note">${esc(fmtDate(s.updatedAt||s.createdAt))}</span></div></div><div class="atelier-row-actions"><button class="atelier-btn" onclick="go('atelier-project/${encodeURIComponent(pid)}')">Projet</button><button class="atelier-btn" onclick="atelierRenameSession('${pid}','${sid}')">Renommer</button></div></div>
 <div class="atelier-progress">${progress.map(x=>`<div class="${x?'on':''}"></div>`).join('')}</div>
 <div class="atelier-columns"><div>
 ${problemBlock(pid,s)}
 ${materialSection(pid,s)}
 ${atlas1Section(pid,s)}
 ${openSection(pid,s)}
 ${constraintSection(pid,s)}
 ${convergeSection(pid,s)}
 ${testSection(pid,s)}
 ${decisionSection(pid,s)}
 ${auditSection(audits)}
 </div><aside class="atelier-side">${sidePanel(pid,s)}${returnBlock(pid,s)}</aside></div>`;
}
function problemBlock(pid,s){return `<details class="atelier-section" open><summary><h3><span class="atelier-step">1</span>FORMULER</h3><span>Problème singulier</span></summary><div class="atelier-section-body"><div class="atelier-problem"><div class="atelier-kicker">Problème actuel</div><p class="atelier-note">Formule ce qui résiste dans l’œuvre en langage ordinaire. Le problème n’est pas le nom d’un concept à appliquer : il doit décrire une difficulté singulière suffisamment précise pour éliminer certaines réponses.</p><textarea class="atelier-textarea" placeholder="Qu’est-ce qui résiste actuellement dans l’œuvre ?" onchange="atelierSetProblem('${pid}','${s.id}',this.value)">${esc(s.activeProblem||'')}</textarea><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddExclusion('${pid}','${s.id}')">＋ Ce que le problème n’est pas</button><button class="atelier-btn ghost" onclick="atelierShowProblemHistory('${pid}','${s.id}')">Historique (${(s.formulations||[]).length})</button></div>${(s.exclusions||[]).map((x,i)=>`<div class="atelier-note">≠ ${esc(x)} <button class="atelier-btn ghost" onclick="atelierRemoveExclusion('${pid}','${s.id}',${i})">×</button></div>`).join('')}</div></div></details>`}
function materialSection(pid,s){return `<details class="atelier-section"><summary><h3>DONNÉ / HYPOTHÈSES</h3><span>Matériau de la session</span></summary><div class="atelier-section-body"><p class="atelier-note">Avant d’ouvrir des possibilités, sépare ce qui appartient réellement au projet de ce qui n’est encore qu’hypothèse, candidat ou inconnue. Ce registre soutient FORMULER sans constituer une étape supplémentaire.</p><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddSessionMaterial('${pid}','${s.id}')">＋ Élément</button></div>${(s.materials||[]).length?(s.materials||[]).map(m=>sessionMaterialRow(pid,s,m)).join(''):'<div class="atelier-empty">Ajoute les éléments de la session qui doivent être distingués.</div>'}</div></details>`}
function sessionMaterialRow(pid,s,m){return `<div class="atelier-row"><div class="atelier-row-main"><b>${esc(m.text)}</b>${m.note?`<small>${esc(m.note)}</small>`:''}</div><div class="atelier-row-actions"><select class="atelier-status-select" onchange="atelierSetSessionMaterialStatus('${pid}','${s.id}','${m.id}',this.value)">${statusOptions(m.status||'given',['given','hypothesis','candidate','locked','rejected','open'])}</select><button class="atelier-btn ghost" onclick="atelierDeleteSessionMaterial('${pid}','${s.id}','${m.id}')">×</button></div></div>`}

function atlas1Section(pid,s){
 const engine=window.ATLAS1_OPERATIVE;if(!engine)return '';
 const st=engine.ensureState(s),gate=engine.atlas2Gate(s);
 const statusLabel={not_run:'NON EXÉCUTÉ',pre_routed:'PRÉ-ROUTÉ',no_structural_alert:'AUCUNE ALERTE STRUCTURELLE',running:'EN COURS',stabilized:'STABILISÉ',insufficient:'MATÉRIAU INSUFFISANT'}[st.status]||String(st.status||'').toUpperCase();
 const diagnostics=(st.diagnostics||[]).map(d=>{const spec=engine.diagnosticById(d.id);return `<div class="atelier-a1-diagnostic"><span class="atelier-a1-code">${esc(d.id)}</span><div><b>${esc(spec?.label||d.id)}</b><p>${esc(d.reason||spec?.detects||'')}</p></div></div>`}).join('');
 const ops=(st.selectedOperators||[]).map(x=>{const o=engine.operatorById(x.id);return `<div class="atelier-a1-op"><div><span class="atelier-a1-family">${esc(engine.families[o?.family]?.label||o?.family||'')}</span><b>${esc(o?.label||x.label||x.id)}</b><small>${esc(o?.sourceWork||x.sourceWork||'Atlas 1')}</small></div><p>${esc(o?.operation||'')}</p></div>`}).join('');
 const runs=(st.operationRuns||[]).slice(-5).map(r=>{const o=engine.operatorById(r.operatorId);return `<div class="atelier-a1-run ${r.status==='productive'?'productive':'quiet'}"><b>${esc(o?.label||r.operatorId)}</b><small>${esc(r.status==='productive'?'DELTA PRODUCTIF':'AUCUN DELTA SIGNIFICATIF')}</small>${(r.delta||[]).map(x=>`<p>→ ${esc(typeof x==='string'?x:JSON.stringify(x))}</p>`).join('')}</div>`}).join('');
 const outputs=[
  ['CONTRAINTES FORTES',st.strongConstraints],['DÉPLACEMENTS FERTILES',st.fertileDisplacements],['TENSIONS PRODUCTIVES',st.productiveTensions]
 ].filter(([,a])=>(a||[]).length).map(([label,a])=>`<div class="atelier-a1-output"><b>${label}</b>${a.map(x=>`<p>→ ${esc(typeof x==='string'?x:JSON.stringify(x))}</p>`).join('')}</div>`).join('');
 return `<details class="atelier-section atelier-a1-section"><summary><h3>TRACE ATLAS 1 · MOTEUR OPÉRATOIRE</h3><span>${esc(statusLabel)} · ${(st.diagnostics||[]).length} diagnostic(s) · ${(st.selectedOperators||[]).length} opérateur(s)</span></summary><div class="atelier-section-body"><p class="atelier-note"><strong>Atlas 1 pense ; il ne scénarise pas.</strong> Cette trace montre le pré-routage structurel : diagnostics → familles → opérateurs. Aucun concept n’est sélectionné par simple mot-clé. Les opérations sémantiques doivent produire un delta réel avant d’influencer le tri de l’Atelier.</p><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAtlas1PreRoute('${pid}','${s.id}')">Actualiser le pré-routage</button><button class="atelier-btn ghost" onclick="atelierAtlas1ShowGate('${pid}','${s.id}')">Gate Atlas 2</button></div>${diagnostics?`<div class="atelier-a1-grid"><div><div class="atelier-kicker">DIAGNOSTICS STRUCTURELS</div>${diagnostics}</div><div><div class="atelier-kicker">OPÉRATEURS SÉLECTIONNÉS</div>${ops||'<div class="atelier-empty">Aucun opérateur nécessaire à partir des seuls signaux structurels.</div>'}</div></div>`:'<div class="atelier-empty">Aucune alerte structurelle détectée. Cela ne remplace pas l’analyse sémantique du matériau.</div>'}${runs?`<div class="atelier-kicker atelier-a1-gap">DERNIERS RUNS</div>${runs}`:''}${outputs?`<div class="atelier-kicker atelier-a1-gap">SORTIES CONSERVÉES</div>${outputs}`:''}<div class="atelier-a1-gate ${gate.ready?'ready':'blocked'}"><b>${gate.ready?'GATE ATLAS 2 · STRUCTURE PRÊTE':'GATE ATLAS 2 · BLOQUÉ'}</b><span>${gate.ready?'Aucun blocage structurel déterministe. Le passage reste soumis à la qualité de l’analyse sémantique.':esc(gate.blockers.join(' · '))}</span></div></div></details>`;
}
function openSection(pid,s){return `<details class="atelier-section"><summary><h3><span class="atelier-step">2</span>OUVRIR</h3><span>Raccords Atlas</span></summary><div class="atelier-section-body"><p class="atelier-note">Recherche dans <strong>Atlas 1 et Atlas 2</strong>. OUVRIR ne sert pas à accumuler une bibliothèque : retiens seulement quelques prises dont tu peux expliquer pourquoi elles déplacent le problème actuel.</p><div class="atelier-field"><input id="atelierAtlasQuery" class="atelier-input" placeholder="Chercher auteur, œuvre, concept…" oninput="atelierAtlasSearch('${pid}','${s.id}',this.value)"><div id="atelierAtlasResults" class="atelier-atlas-results"></div></div>${(s.resources||[]).map(r=>resourceRow(pid,s,r)).join('')||'<div class="atelier-empty">Aucun raccord retenu.</div>'}</div></details>`}
function resourceRow(pid,s,r){return `<div class="atelier-row"><div class="atelier-row-main"><b>${esc(r.label)}</b><small>${esc(r.reason||r.operation||'Raccord Atlas')}</small></div><div class="atelier-row-actions">${r.page?`<button class="atelier-btn" onclick="go('${esc(r.page)}')">Voir</button>`:''}<button class="atelier-btn ghost" onclick="atelierRemoveResource('${pid}','${s.id}','${r.id}')">×</button></div></div>`}
function constraintSection(pid,s){return `<details class="atelier-section" open><summary><h3><span class="atelier-step">3</span>CONTRAINDRE</h3><span>${(s.constraints||[]).length} contrainte(s)</span></summary><div class="atelier-section-body"><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddConstraint('${pid}','${s.id}')">＋ Contrainte</button></div>${(s.constraints||[]).map(c=>constraintRow(pid,s,c)).join('')||'<div class="atelier-empty">Une bonne contrainte élimine les solutions qui trahissent le problème.</div>'}</div></details>`}
function constraintRow(pid,s,c){return `<div class="atelier-row"><div class="atelier-row-main"><b>${esc(c.text)}</b><small>${esc(c.reason||'')}</small></div><div class="atelier-row-actions"><select class="atelier-status-select" onchange="atelierSetConstraintStatus('${pid}','${s.id}','${c.id}',this.value)">${statusOptions(c.status||'active',['active','locked','open','rejected'])}</select><button class="atelier-btn ghost" onclick="atelierDeleteConstraint('${pid}','${s.id}','${c.id}')">×</button></div></div>`}
function convergeSection(pid,s){return `<details class="atelier-section" open><summary><h3><span class="atelier-step">4</span>CONVERGER</h3><span>Lignes actives</span></summary><div class="atelier-section-body"><p class="atelier-note"><strong>Règle LOCK :</strong> une chaîne d’expressions reliées par des flèches peut résumer une ligne, mais elle ne peut jamais en être l’explication. Le contexte qui a produit les termes doit rester visible juste à côté.</p><p class="atelier-note"><strong>SUCCESSION ≠ CAUSALITÉ.</strong> Lorsqu’une ligne condense plusieurs éléments, précise la nature de leur relation : causalité, condition, contrainte, transformation, succession, accumulation, répétition/variation, parallélisme, contamination, requalification, association/montage, rituel/programme ou champ distribué.</p><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddLine('${pid}','${s.id}')">＋ Ligne</button></div>${(s.lines||[]).map(l=>`<div class="atelier-line-card ${l.context&&l.relationType?'':'needs-context'}"><b>${esc(l.label)}</b><div class="atelier-line-sequence">${esc(l.elements||'')}</div><label class="atelier-label">NATURE DE LA RELATION</label><select class="atelier-select" onchange="atelierSetLineRelation('${pid}','${s.id}','${l.id}',this.value)">${relationOptions(l.relationType||'')}</select>${l.relationType?`<p class="atelier-relation-help"><strong>${esc(RELATION_LABEL[l.relationType]||l.relationType)}.</strong> ${esc(relationHelp(l.relationType))}</p>`:`<p class="atelier-context-missing">Relation non qualifiée : les flèches ne doivent jamais laisser supposer automatiquement une causalité.</p>`}${l.context?`<p>${esc(l.context)}</p>`:`<p class="atelier-context-missing">Contexte manquant : cette condensation visuelle ne suffit pas à expliquer la ligne.</p>`}<div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierEditLine('${pid}','${s.id}','${l.id}')">Éditer / contextualiser</button><button class="atelier-btn ghost" onclick="atelierDeleteLine('${pid}','${s.id}','${l.id}')">Supprimer</button></div></div>`).join('')||'<div class="atelier-empty">Aucune ligne active.</div>'}</div></details>`}
function testSection(pid,s){return `<details class="atelier-section" open><summary><h3><span class="atelier-step">5</span>TESTER</h3><span>${(s.candidates||[]).length} candidat(s)</span></summary><div class="atelier-section-body"><div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddCandidate('${pid}','${s.id}')">＋ Candidat</button></div>${(s.candidates||[]).map(c=>candidateCard(pid,s,c)).join('')||'<div class="atelier-empty">Ajoute un geste, une scène, un motif, une structure, un personnage ou une règle à éprouver.</div>'}</div></details>`}

function candidateCard(pid,s,c){const decision=(s.decisions||[]).find(d=>d.candidateId===c.id);const activeLines=(s.lines||[]).filter(l=>c.supportsLines?.includes(l.id));return `<article class="atelier-candidate"><div class="atelier-candidate-head"><div><div class="type">${esc(c.type||'forme')}</div><h4>${esc(c.label)}</h4>${c.description?`<p class="atelier-candidate-context">${esc(c.description)}</p>`:''}<p class="atelier-density"><strong>DENSITÉ FORMELLE · ${activeLines.length} ligne${activeLines.length>1?'s':''}</strong> — indicateur de concentration, jamais score de sélection. Une forme devient intéressante quand plusieurs nécessités différentes peuvent réellement dépendre d’elle.</p></div>${pill(c.status||'candidate')}</div><div class="atelier-line-links">${(s.lines||[]).map(l=>`<label class="atelier-line-toggle"><input type="checkbox" ${c.supportsLines?.includes(l.id)?'checked':''} onchange="atelierToggleCandidateLine('${pid}','${s.id}','${c.id}','${l.id}',this.checked)">${esc(l.label)}</label>`).join('')}</div><div class="atelier-tests">${TEST_KEYS.map(([k,label])=>testRow(pid,s,c,k,label)).join('')}</div><div class="atelier-decision-bar"><button class="atelier-btn gold" onclick="atelierDecide('${pid}','${s.id}','${c.id}','keep')">Conserver</button><button class="atelier-btn" onclick="atelierDecide('${pid}','${s.id}','${c.id}','demote')">Rétrograder</button><button class="atelier-btn danger" onclick="atelierDecide('${pid}','${s.id}','${c.id}','reject')">Rejeter</button><button class="atelier-btn" onclick="atelierDecide('${pid}','${s.id}','${c.id}','leave_open')">Laisser ouvert</button>${decision?.action==='keep'?`<button class="atelier-btn primary" onclick="atelierPromoteFinalDecision('${pid}','${s.id}','${c.id}')">Élever en décision singulière</button>`:''}<button class="atelier-btn ghost" onclick="atelierDeleteCandidate('${pid}','${s.id}','${c.id}')">×</button></div>${decision?`<div class="atelier-note"><strong>${DECISION_LABEL[decision.action]}</strong> · ${esc(decision.reason||'')}</div>`:''}</article>`}
function testRow(pid,s,c,k,label){const t=(c.tests||{})[k]||{};const help={necessity:'Combien de lignes du problème dépendent réellement de cette forme ?',substitutability:'À quel point peut-on la remplacer sans abîmer l’œuvre ? Ici, une substituabilité faible signifie une forte résistance au remplacement.',excess:'Produit-elle davantage que la fonction pour laquelle elle avait été imaginée ?',materiality:'Existe-t-elle concrètement dans le médium, au-delà d’un simple commentaire conceptuel ?',consequence:'Oblige-t-elle d’autres éléments de l’œuvre à changer ?'}[k]||'';return `<div class="atelier-test"><label title="${esc(help)}">${label}</label><select class="atelier-select" title="${esc(help)}" onchange="atelierSetTest('${pid}','${s.id}','${c.id}','${k}','level',this.value)">${levelOptions(t.level||'')}</select><input class="atelier-input" value="${esc(t.reason||'')}" placeholder="Pourquoi ?" title="${esc(help)}" onchange="atelierSetTest('${pid}','${s.id}','${c.id}','${k}','reason',this.value)"></div>`}
function decisionSection(pid,s){return `<details class="atelier-section" open><summary><h3><span class="atelier-step">6</span>TRANCHER</h3><span>${(s.decisions||[]).length} décision(s)</span></summary><div class="atelier-section-body">${(s.decisions||[]).map(d=>decisionCard(pid,s,d)).join('')||'<div class="atelier-empty">Aucune décision. Trancher signifie conserver, rétrograder, rejeter ou laisser ouvert.</div>'}<div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddOpenQuestion('${pid}','${s.id}')">＋ Question ouverte</button></div></div></details>`}
function decisionCard(pid,s,d){const c=(s.candidates||[]).find(x=>x.id===d.candidateId);const cons=(s.consequences||[]).filter(x=>x.originDecision===d.id);return `<div class="atelier-decision"><b>${esc(DECISION_LABEL[d.action]||d.action)} · ${esc(c?.label||'Décision')}</b><p>${esc(d.reason||'')}</p>${cons.map(x=>`<div class="atelier-consequence">→ ${esc(x.text)} <button class="atelier-btn ghost" onclick="atelierDeleteConsequence('${pid}','${s.id}','${x.id}')">×</button></div>`).join('')}<div class="atelier-toolbar"><button class="atelier-btn" onclick="atelierAddConsequence('${pid}','${s.id}','${d.id}')">＋ Conséquence</button><button class="atelier-btn ghost" onclick="atelierWhy('${pid}','${s.id}','${d.id}')">Pourquoi ?</button></div></div>`}
function auditSection(audits){return `<details class="atelier-section"><summary><h3>Audits de session</h3><span>${audits.filter(a=>a.level!=='good').length} alerte(s)</span></summary><div class="atelier-section-body">${audits.map(a=>`<div class="atelier-audit ${a.level}"><b>${esc(a.title)}</b>${esc(a.text)}</div>`).join('')}<div class="atelier-note"><strong>Limite V1 :</strong> ces audits sont mécaniques. Un audit sémantique de contradictions, redondances profondes et sur-convergence devra être confié au moteur IA lorsqu’il sera branché.</div></div></details>`}
function sidePanel(pid,s){const locked=(s.constraints||[]).filter(x=>x.status==='locked');const decisions=(s.decisions||[]).filter(x=>x.status==='locked');return `<section class="atelier-card"><div class="atelier-kicker">LOCKS</div>${locked.map(x=>`<div class="atelier-row-main"><b>${esc(x.text)}</b></div>`).join('')||'<p>Aucun LOCK.</p>'}</section><section class="atelier-card"><div class="atelier-kicker">QUESTIONS OUVERTES</div>${(s.openQuestions||[]).map(q=>`<div class="atelier-row"><div class="atelier-row-main"><b>${esc(q.text)}</b><small>${esc(q.reason||'')}</small></div><button class="atelier-btn ghost" onclick="atelierDeleteOpenQuestion('${pid}','${s.id}','${q.id}')">×</button></div>`).join('')||'<p>Aucune question explicitement ouverte.</p>'}</section><section class="atelier-card"><div class="atelier-kicker">DÉCISIONS</div><p>${decisions.length} décision(s) verrouillée(s) · ${(s.consequences||[]).length} conséquence(s).</p></section>`}
function returnBlock(pid,s){const ready=!!s.activeProblem&&(s.decisions||[]).length>0;const kept=(s.decisions||[]).some(d=>d.action==='keep');return `<div class="atelier-return"><strong>Vers l’Œuvre</strong><span>${ready?'La session possède un problème formulé et des décisions traçables. L’étage ŒUVRE ne choisit rien à ta place : il formalise seulement la forme que tu décides de retenir et les conséquences qu’elle impose.':'La session peut rester ouverte. Il manque encore au moins un problème formulé ou une décision.'}</span>${kept?`<button class="atelier-btn" onclick="go('oeuvre-decision/${encodeURIComponent(pid)}/${encodeURIComponent(s.id)}')">ŒUVRE · décision singulière</button>`:''}${s.status==='closed'?`<button class="atelier-btn ghost" onclick="atelierReopenSession('${pid}','${s.id}')">Rouvrir la session</button>`:`<button class="atelier-btn ghost" onclick="atelierCloseSession('${pid}','${s.id}')">Fermer la session</button>`}</div>`}

function computeAudits(s){const out=[];const candidates=s.candidates||[];const lines=s.lines||[];const consequences=s.consequences||[];const decisions=s.decisions||[];
 const duplicates=[...new Set(candidates.map(c=>norm(c.label)).filter((x,i,a)=>x&&a.indexOf(x)!==i))];out.push(duplicates.length?{level:'warn',title:'Redondance',text:`${duplicates.length} candidat(s) semblent dupliqués textuellement.`}:{level:'good',title:'Redondance',text:'Aucun doublon textuel évident.'});
 const condensedWithoutContext=lines.filter(l=>String(l.elements||'').includes('→')&&!String(l.context||'').trim());out.push(condensedWithoutContext.length?{level:'bad',title:'Contextualisation des lignes',text:`${condensedWithoutContext.length} ligne(s) utilisent une chaîne à flèches sans explication contextuelle à proximité.`}:{level:'good',title:'Contextualisation des lignes',text:'Toute condensation visuelle par flèches possède une explication contextuelle.'});
 const untypedRelations=lines.filter(l=>String(l.elements||'').trim()&&!String(l.relationType||'').trim());out.push(untypedRelations.length?{level:'bad',title:'Nature des relations',text:`${untypedRelations.length} ligne(s) ne précisent pas si leurs éléments relèvent d’une causalité, condition, contrainte, succession, variation, association ou autre relation.`}:{level:'good',title:'Nature des relations',text:'Chaque ligne condensée qualifie explicitement la nature de la relation entre ses éléments ; aucune flèche ne signifie causalité par défaut.'});
 const weakResources=(s.resources||[]).filter(r=>String(r.reason||'').trim().split(/\s+/).filter(Boolean).length<6);out.push(weakResources.length?{level:'bad',title:'Contextualisation des raccords Atlas',text:`${weakResources.length} raccord(s) Atlas sont nommés sans expliquer suffisamment ce qu’ils font dans ce problème.`}:{level:'good',title:'Contextualisation des raccords Atlas',text:'Chaque raccord Atlas retenu possède une raison contextuelle explicite.'});
 const weak=candidates.filter(c=>!c.supportsLines?.length&&!decisions.some(d=>d.candidateId===c.id)&&!['rejected','demoted'].includes(c.status));out.push(weak.length?{level:'warn',title:'Nécessité',text:`${weak.length} candidat(s) ne portent encore aucune ligne et n’ont pas été tranchés.`}:{level:'good',title:'Nécessité',text:'Les candidats actifs sont reliés à une ligne ou déjà tranchés.'});
 const orphans=consequences.filter(c=>!decisions.some(d=>d.id===c.originDecision));out.push(orphans.length?{level:'bad',title:'Contradiction structurelle',text:`${orphans.length} conséquence(s) n’ont plus de décision d’origine.`}:{level:'good',title:'Contradiction structurelle',text:'Aucune conséquence orpheline détectée.'});
 if(lines.length&&candidates.length>=3){const counts=lines.map(l=>({l,n:candidates.filter(c=>c.supportsLines?.includes(l.id)&&!['rejected'].includes(c.status)).length})).sort((a,b)=>b.n-a.n);const active=candidates.filter(c=>c.status!=='rejected').length;const top=counts[0];if(top&&active>=3&&top.n===active)out.push({level:'warn',title:'Sur-convergence',text:`Tous les candidats actifs passent actuellement par la ligne « ${top.l.label} ». Vérifier qu’elle n’absorbe pas tout le film.`});else out.push({level:'good',title:'Sur-convergence',text:'Aucune concentration mécanique totale sur une seule ligne.'})}else out.push({level:'good',title:'Sur-convergence',text:'Pas assez de candidats reliés pour signaler une sur-convergence mécanique.'});return out}

function atlasSearchData(q){const n=norm(q);if(!n)return[];const hits=[];
 (AUTHORS||[]).forEach(a=>{if(norm(a.name+' '+a.desc).includes(n))hits.push({type:'Auteur',label:a.name,page:a.page,desc:a.desc})});
 (WORKS||[]).forEach(w=>{if(norm((w.title||'')+' '+(w.desc||'')+' '+(w.year||'')).includes(n))hits.push({type:'Œuvre',label:w.title,page:w.page,desc:w.desc||''})});
 Object.keys(GLOSS||{}).forEach(name=>{const g=GLOSS[name]||{};if(norm(name+' '+(g.hook||'')+' '+(g.definition||'')).includes(n))hits.push({type:'Concept',label:name,page:'concept/'+encodeURIComponent(name),desc:g.hook||g.definition||''})});
 return hits.slice(0,10)}

// ---- actions globales
window.atelierNewProject=async()=>{const title=prompt('Nom du projet :');if(!title)return;const p=newProject(title.trim());await putProject(p);go('atelier-project/'+encodeURIComponent(p.id))};
window.atelierRenameProject=async pid=>{const p=await getProject(pid);if(!p)return;const title=prompt('Nouveau nom :',p.title);if(!title)return;await mutateProject(pid,x=>{x.title=title.trim()});rerender()};
window.atelierDeleteProject=async pid=>{if(!confirm('Supprimer ce projet et ses sessions ?'))return;const p=await getProject(pid);for(const m of (p?.materials||[]))if(m.fileId)await deleteFile(m.fileId);await deleteProjectRecord(pid);go('atelier')};
window.atelierExportProject=async pid=>{const p=await getProject(pid);if(!p)return;const data=clone(p);data.exportedAt=now();data.exportVersion=1;data.materials=(data.materials||[]).map(m=>m.fileId?{...m,fileMissingFromExport:true}:m);const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(p.title||'atelier').replace(/[^a-z0-9_-]+/gi,'_')+'.atelier.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
window.atelierImportProject=async input=>{const f=input.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data.title)throw new Error('Projet invalide');const old=await getProject(data.id);if(old)data.id=id('project');data.updatedAt=now();data.sessions=(data.sessions||[]).map(s=>({...newSession(s.title),...s,id:s.id||id('session')}));await putProject(data);input.value='';rerender()}catch(e){alert('Import impossible : '+e.message)}};
window.atelierAddNote=async pid=>{const title=prompt('Titre de la note :');if(!title)return;const content=prompt('Contenu :')||'';await mutateProject(pid,p=>p.materials.push({id:id('mat'),type:'note',title:title.trim(),content,status:'given',createdAt:now()}));rerender()};
window.atelierAttachFile=async(pid,input)=>{const f=input.files?.[0];if(!f)return;const fid=id('file');await putFile({id:fid,projectId:pid,name:f.name,type:f.type,size:f.size,blob:f,createdAt:now()});await mutateProject(pid,p=>p.materials.push({id:id('mat'),type:'document',title:f.name,fileName:f.name,fileId:fid,size:f.size,mime:f.type,extension:(f.name.split('.').pop()||'file'),status:'given',createdAt:now()}));input.value='';rerender()};
window.atelierDownloadFile=async fid=>{const f=await getFile(fid);if(!f){alert('Fichier local introuvable.');return}const url=URL.createObjectURL(f.blob);const a=document.createElement('a');a.href=url;a.download=f.name||'document';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)};
window.atelierSetMaterialStatus=async(pid,mid,status)=>{await mutateProject(pid,p=>{const m=p.materials.find(x=>x.id===mid);if(m)m.status=status});rerender()};
window.atelierDeleteMaterial=async(pid,mid)=>{if(!confirm('Retirer ce matériau ?'))return;let fid=null;await mutateProject(pid,p=>{const m=p.materials.find(x=>x.id===mid);fid=m?.fileId||null;p.materials=p.materials.filter(x=>x.id!==mid)});if(fid)await deleteFile(fid);rerender()};
window.atelierNewSession=async pid=>{const title=prompt('Nom de la session :','Nouveau problème');if(!title)return;let sid;await mutateProject(pid,p=>{const s=newSession(title.trim());sid=s.id;p.sessions.push(s)});go('atelier-session/'+encodeURIComponent(pid)+'/'+encodeURIComponent(sid))};
window.atelierRenameSession=async(pid,sid)=>{const p=await getProject(pid),s=p&&findSession(p,sid);if(!s)return;const title=prompt('Nom de la session :',s.title);if(!title)return;await mutateProject(pid,p2=>{const s2=findSession(p2,sid);s2.title=title.trim();s2.updatedAt=now()});rerender()};
window.atelierSetProblem=async(pid,sid,text)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);const t=text.trim();if(t===s.activeProblem)return;s.activeProblem=t;const v=(s.formulations?.length||0)+1;s.formulations=s.formulations||[];s.formulations.forEach(x=>{if(x.status==='active')x.status='demoted'});if(t)s.formulations.push({id:id('problem'),version:v,text:t,status:'active',createdAt:now()});s.updatedAt=now()})};
window.atelierShowProblemHistory=async(pid,sid)=>{const p=await getProject(pid),s=p&&findSession(p,sid);if(!s)return;alert((s.formulations||[]).map(x=>`V${x.version} · ${STATUS_LABEL[x.status]||x.status}\n${x.text}`).join('\n\n')||'Aucun historique.')};
window.atelierAddExclusion=async(pid,sid)=>{const text=prompt('Le problème n’est pas…');if(!text)return;await mutateProject(pid,p=>{const s=findSession(p,sid);s.exclusions=s.exclusions||[];s.exclusions.push(text.trim());s.updatedAt=now()});rerender()};
window.atelierRemoveExclusion=async(pid,sid,i)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.exclusions.splice(i,1);s.updatedAt=now()});rerender()};
window.atelierAddSessionMaterial=async(pid,sid)=>{const text=prompt('Élément à distinguer :');if(!text)return;const status=prompt('Statut : given / hypothesis / candidate / open','given')||'given';await mutateProject(pid,p=>{const s=findSession(p,sid);s.materials.push({id:id('smat'),text:text.trim(),status:STATUS.includes(status)?status:'given'});s.updatedAt=now()});rerender()};
window.atelierSetSessionMaterialStatus=async(pid,sid,mid,status)=>{await mutateProject(pid,p=>{const s=findSession(p,sid),m=s.materials.find(x=>x.id===mid);if(m)m.status=status;s.updatedAt=now()});rerender()};
window.atelierDeleteSessionMaterial=async(pid,sid,mid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.materials=s.materials.filter(x=>x.id!==mid);s.updatedAt=now()});rerender()};
window.atelierAtlasSearch=(pid,sid,q)=>{const box=document.getElementById('atelierAtlasResults');if(!box)return;const hits=atlasSearchData(q);box.innerHTML=hits.map(h=>`<button class="atelier-atlas-hit" onclick="atelierAttachAtlasResource('${pid}','${sid}','${encodeURIComponent(h.type)}','${encodeURIComponent(h.page)}','${encodeURIComponent(h.label)}')"><b>${esc(h.label)}</b><span>${esc(h.type)} · ${esc((h.desc||'').slice(0,150))}</span></button>`).join('')};
window.atelierAttachAtlasResource=async(pid,sid,type,page,label)=>{type=decodeURIComponent(type);page=decodeURIComponent(page);label=decodeURIComponent(label);const reason=(prompt('Pourquoi ce raccord est-il utile maintenant ?','')||'').trim();if(reason.split(/\s+/).filter(Boolean).length<6){alert('Le raccord n’est pas ajouté : explique en quelques mots ce qu’il fait dans ce problème. Un nom de concept isolé ne suffit pas.');return}const atlas=type.startsWith('Atlas 2')?'atlas2':'atlas1';await mutateProject(pid,p=>{const s=findSession(p,sid);if(!s.resources.some(r=>r.page===page))s.resources.push({id:id('resource'),atlas,type,page,label,reason,status:'active'});s.updatedAt=now()});rerender()};
window.atelierRemoveResource=async(pid,sid,rid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.resources=s.resources.filter(x=>x.id!==rid);s.updatedAt=now()});rerender()};
window.atelierAtlas1PreRoute=async(pid,sid)=>{if(!window.ATLAS1_OPERATIVE)return;await mutateProject(pid,p=>{const s=findSession(p,sid);window.ATLAS1_OPERATIVE.preRoute(s);s.updatedAt=now()});rerender()};
window.atelierAtlas1ShowGate=async(pid,sid)=>{const p=await getProject(pid),s=p&&findSession(p,sid);if(!s||!window.ATLAS1_OPERATIVE)return;const g=window.ATLAS1_OPERATIVE.atlas2Gate(s);alert(`${g.ready?'GATE ATLAS 2 · STRUCTURE PRÊTE':'GATE ATLAS 2 · BLOQUÉ'}\n\n${g.blockers.length?g.blockers.map(x=>'• '+x).join('\n'):'Aucun blocage structurel déterministe.'}\n\nDiagnostics : ${g.stateSummary.diagnostics}\nRuns : ${g.stateSummary.runs}\nContraintes fortes : ${g.stateSummary.strongConstraints}\nDéplacements fertiles : ${g.stateSummary.fertileDisplacements}`)};
window.atelierAddConstraint=async(pid,sid)=>{const text=prompt('Contrainte :');if(!text)return;const reason=prompt('Pourquoi cette contrainte protège-t-elle le problème ?','')||'';await mutateProject(pid,p=>{const s=findSession(p,sid);s.constraints.push({id:id('constraint'),text:text.trim(),reason,status:'active'});s.updatedAt=now()});rerender()};
window.atelierSetConstraintStatus=async(pid,sid,cid,status)=>{await mutateProject(pid,p=>{const s=findSession(p,sid),c=s.constraints.find(x=>x.id===cid);if(c)c.status=status;s.updatedAt=now()});rerender()};
window.atelierDeleteConstraint=async(pid,sid,cid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.constraints=s.constraints.filter(x=>x.id!==cid);s.updatedAt=now()});rerender()};
window.atelierAddLine=async(pid,sid)=>{const label=prompt('Nom de la ligne :');if(!label)return;const elements=prompt('Synthèse visuelle / éléments (les flèches sont autorisées) :','')||'';const context=prompt('Explique le contexte : que désignent concrètement ces termes ici et quelle relation entretiennent-ils ?','')||'';await mutateProject(pid,p=>{const s=findSession(p,sid);s.lines.push({id:id('line'),label:label.trim(),elements,relationType:'',context:context.trim()});s.updatedAt=now()});rerender()};
window.atelierSetLineRelation=async(pid,sid,lid,value)=>{await mutateProject(pid,p=>{const s=findSession(p,sid),l=s.lines.find(x=>x.id===lid);if(!l)return;l.relationType=String(value||'').trim();s.updatedAt=now()});rerender()};
window.atelierEditLine=async(pid,sid,lid)=>{const p=await getProject(pid),s=p&&findSession(p,sid),l=s?.lines.find(x=>x.id===lid);if(!l)return;const label=prompt('Nom de la ligne :',l.label);if(!label)return;const elements=prompt('Synthèse visuelle / éléments :',l.elements||'');if(elements===null)return;const context=prompt('Explication contextuelle obligatoire si la ligne est condensée par des flèches :',l.context||'');if(context===null)return;await mutateProject(pid,p2=>{const s2=findSession(p2,sid),l2=s2.lines.find(x=>x.id===lid);if(!l2)return;l2.label=label.trim();l2.elements=elements.trim();l2.context=context.trim();s2.updatedAt=now()});rerender()};
window.atelierDeleteLine=async(pid,sid,lid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.lines=s.lines.filter(x=>x.id!==lid);s.candidates.forEach(c=>c.supportsLines=(c.supportsLines||[]).filter(x=>x!==lid));s.updatedAt=now()});rerender()};
window.atelierAddCandidate=async(pid,sid)=>{const type=prompt('Type : geste / scène / motif / structure / personnage / règle / objet','structure')||'structure';const label=prompt('Candidat à éprouver :');if(!label)return;const description=prompt('Dans quel contexte concret ce candidat agit-il et que pourrait-il transformer ?','')||'';await mutateProject(pid,p=>{const s=findSession(p,sid);s.candidates.push({id:id('candidate'),type,label:label.trim(),description:description.trim(),status:'candidate',supportsLines:[],tests:{},createdAt:now()});s.updatedAt=now()});rerender()};
window.atelierDeleteCandidate=async(pid,sid,cid)=>{if(!confirm('Supprimer ce candidat et ses décisions associées ?'))return;await mutateProject(pid,p=>{const s=findSession(p,sid);const dids=s.decisions.filter(d=>d.candidateId===cid).map(d=>d.id);s.candidates=s.candidates.filter(x=>x.id!==cid);s.decisions=s.decisions.filter(x=>x.candidateId!==cid);s.consequences=s.consequences.filter(x=>!dids.includes(x.originDecision));s.updatedAt=now()});rerender()};
window.atelierToggleCandidateLine=async(pid,sid,cid,lid,on)=>{await mutateProject(pid,p=>{const s=findSession(p,sid),c=s.candidates.find(x=>x.id===cid);c.supportsLines=c.supportsLines||[];c.supportsLines=on?[...new Set([...c.supportsLines,lid])]:c.supportsLines.filter(x=>x!==lid);s.updatedAt=now()})};
window.atelierSetTest=async(pid,sid,cid,key,field,value)=>{await mutateProject(pid,p=>{const s=findSession(p,sid),c=s.candidates.find(x=>x.id===cid);c.tests=c.tests||{};c.tests[key]=c.tests[key]||{};c.tests[key][field]=value;s.updatedAt=now()})};
window.atelierDecide=async(pid,sid,cid,action)=>{const reason=prompt('Pourquoi cette décision ?','');if(reason===null)return;await mutateProject(pid,p=>{const s=findSession(p,sid),c=s.candidates.find(x=>x.id===cid);let d=s.decisions.find(x=>x.candidateId===cid);if(!d){d={id:id('decision'),candidateId:cid,createdAt:now()};s.decisions.push(d)}d.action=action;d.reason=reason.trim();d.status='locked';d.updatedAt=now();c.status=action==='keep'?'locked':action==='demote'?'demoted':action==='reject'?'rejected':'open';s.updatedAt=now()});rerender()};
window.atelierAddConsequence=async(pid,sid,did)=>{const text=prompt('Conséquence produite par cette décision :');if(!text)return;await mutateProject(pid,p=>{const s=findSession(p,sid);s.consequences.push({id:id('consequence'),originDecision:did,text:text.trim(),status:'active'});s.updatedAt=now()});rerender()};
window.atelierDeleteConsequence=async(pid,sid,cid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.consequences=s.consequences.filter(x=>x.id!==cid);s.updatedAt=now()});rerender()};
window.atelierAddOpenQuestion=async(pid,sid)=>{const text=prompt('Question à laisser ouverte :');if(!text)return;const reason=prompt('Pourquoi la garder ouverte maintenant ?','')||'';await mutateProject(pid,p=>{const s=findSession(p,sid);s.openQuestions.push({id:id('open'),text:text.trim(),reason,status:'open',keepOpen:true});s.updatedAt=now()});rerender()};
window.atelierDeleteOpenQuestion=async(pid,sid,qid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.openQuestions=s.openQuestions.filter(x=>x.id!==qid);s.updatedAt=now()});rerender()};
window.atelierWhy=async(pid,sid,did)=>{const p=await getProject(pid),s=p&&findSession(p,sid),d=s?.decisions.find(x=>x.id===did);if(!d)return;const c=s.candidates.find(x=>x.id===d.candidateId);const cons=s.consequences.filter(x=>x.originDecision===d.id);alert(`${DECISION_LABEL[d.action]} · ${c?.label||'Décision'}\n\nPOURQUOI\n${d.reason||'—'}\n\nCONSÉQUENCES\n${cons.map(x=>'→ '+x.text).join('\n')||'—'}`)};
window.atelierCloseSession=async(pid,sid)=>{const p=await getProject(pid),s=p&&findSession(p,sid);if(!s)return;if((!s.activeProblem||!(s.decisions||[]).length)&&!confirm('La session est encore peu concentrée. La fermer malgré tout ?'))return;await mutateProject(pid,p2=>{const s2=findSession(p2,sid);s2.status='closed';s2.closedAt=now();s2.updatedAt=now()});rerender()};
window.atelierReopenSession=async(pid,sid)=>{await mutateProject(pid,p=>{const s=findSession(p,sid);s.status='active';s.updatedAt=now()});rerender()};

async function atelierMount(page,arg){try{if(page==='atelier')await mountHome();else if(page==='atelier-project')await mountProject(arg);else if(page==='atelier-session')await mountSession(arg)}catch(e){const root=document.getElementById('atelierRoot');if(root)root.innerHTML=`<div class="atelier-audit bad"><b>Erreur Atelier</b>${esc(e.message)}</div>`;console.error(e)}}

// Greffe navigation / routes sans modifier les dossiers Atlas existants.
if(typeof NAV!=='undefined'&&!NAV.some(n=>n[0]==='atelier'))NAV.push(['atelier','Atelier','Appareil de concentration : projets, sessions, contraintes, candidats, tests et décisions.','◆']);
PAGE_HANDLERS.atelier=atelierHomePage;
PAGE_HANDLERS['atelier-project']=atelierProjectPage;
PAGE_HANDLERS['atelier-session']=atelierSessionPage;
const originalHome=PAGE_HANDLERS.home;
PAGE_HANDLERS.home=function(){return shell(`<div class="home-hero"><div class="orn">✥</div><h2>Atlas deleuzien</h2><div class="gold-rule"></div><p>Cartographier les pensées. Traverser les concepts.</p></div><div class="search">⌕<input placeholder="Rechercher dans l’Atlas…" onkeydown="if(event.key==='Enter'){searchGlobal(this.value)}"></div><div class="nav-grid">${navCard('authors','◉','Auteurs','Les penseurs et les problèmes que Deleuze leur fait porter.')}${navCard('works','▤','Œuvres','Les livres reconstruits comme des machines complètes, avec leurs subtilités et leurs sources.')}${navCard('concepts','✣','Concepts','Le fonctionnement des grandes notions et leurs transformations selon les œuvres.')}${navCard('glossary','▣','Glossaire','Chaque terme technique, ses usages, ses raccords et ses garde-fous.')}${navCard('routes','⌁','Routes','La transformation argumentée d’un problème à travers les œuvres et les auteurs.')}${navCard('interludes','♜','Interludes','Les milieux intellectuels qui rendent les bifurcations de Deleuze intelligibles.')}${navCard('atelier','◆','Atelier','Concentrer un problème créatif, éprouver les formes et conserver la généalogie des décisions.')}</div>`,{home:true,dark:true,title:'Atlas deleuzien',sub:'Cartographier les pensées'})};
const originalAfterRender=afterRender;
afterRender=function(page,arg){originalAfterRender(page,arg);if(page==='atelier'||page==='atelier-project'||page==='atelier-session')requestAnimationFrame(()=>atelierMount(page,arg))};
renderDrawer();render();
})();
